interface HistoryLedgerProps {
  missions: Mission[];
  selectedMission: Mission | null;
  onSelectMission: (mission: Mission | null) => void;
  onStartNewMission: () => void;
}

export const HistoryLedger: React.FC<HistoryLedgerProps> = ({
  missions,
