    await page.screenshot({ path: path.join(outputDir, '5-step4-approved.png') });
  }

  // Next: Test Rejection Screen
  console.log('Resetting and testing rejection scenario...');
  // Click Start Another Mission
  const anotherBtn = await page.evaluateHandle(() => {
    const btns = Array.from(document.querySelectorAll('button'));
    return btns.find(b => b.innerText.includes('Start Another Mission'));
  });
  if (anotherBtn.asElement()) {
    await anotherBtn.asElement().click();
    await new Promise(r => setTimeout(r, 600));
  }

  // Load Pair 2 Before
  const pair2Btn = await page.evaluateHandle(() => {
    const btns = Array.from(document.querySelectorAll('button'));
    return btns.find(b => b.innerText.includes('Pair 2: Test Fake'));
  });
  if (pair2Btn.asElement()) {
    await pair2Btn.asElement().click();
    await new Promise(r => setTimeout(r, 500));
  }

  const proceedBtn2 = await page.evaluateHandle(() => {
    const btns = Array.from(document.querySelectorAll('button'));
    return btns.find(b => b.innerText.includes('Proceed'));
