  if (proceedBtn2.asElement()) {
    await proceedBtn2.asElement().click();
    await new Promise(r => setTimeout(r, 600));
  }

  // Load Pair 2 After (Cat Meme)
  const pair2AfterBtn = await page.evaluateHandle(() => {
    const btns = Array.from(document.querySelectorAll('button'));
    return btns.find(b => b.innerText.includes('Pair 2: Meme'));
  });
  if (pair2AfterBtn.asElement()) {
    await pair2AfterBtn.asElement().click();
    await new Promise(r => setTimeout(r, 500));
  }

  // Submit rejection
  const submitBtn2 = await page.evaluateHandle(() => {
    const btns = Array.from(document.querySelectorAll('button'));
    return btns.find(b => b.innerText.includes('Submit for AI Verification'));
  });
  if (submitBtn2.asElement()) {
    await submitBtn2.asElement().click();
    await new Promise(r => setTimeout(r, 3000));
    console.log('Capturing 6: Step 4 Rejection Result...');
    await page.screenshot({ path: path.join(outputDir, '6-step4-rejected.png') });
  }

  // Navigate to Ledger
