  if (rankNav.asElement()) {
    await rankNav.asElement().click();
    await new Promise(r => setTimeout(r, 800));
    await page.screenshot({ path: path.join(outputDir, '8-leaderboard.png') });
  }

  await browser.close();
  console.log('All screenshots captured successfully into /presentation-assets!');
}

capture().catch(err => {
  console.error('Screenshot error:', err);
  process.exit(1);
});

