// scripts/export-conversation.js
const fs = require('fs');

const inputFilePath = 'transcript_full.jsonl';
const outputFilePath = 'summary.txt';

async function processTranscript() {
    try {
        const fileContent = fs.readFileSync(inputFilePath, 'utf-8');
        const lines = fileContent.trim().split('\n');
        let existingSummary = fs.existsSync(outputFilePath) ? fs.readFileSync(outputFilePath, 'utf-8').trim() : '';
        let newSummary = '';

        for (const line of lines) {
            const data = JSON.parse(line);
            if (data.type === 'PLANNER_RESPONSE') {
                const thinking = data.thinking;
                if (!thinking || thinking.trim() === '') {
                    continue; // Skip if no thinking is present
                }
                const sentences = thinking.split('.').filter(s => s.trim() !== ''); // Split into sentences
                let summaryDelta = '';

                for (const sentence of sentences) {
                    let processedSentence = sentence.trim(); // Trim leading/trailing whitespace
                    processedSentence = processedSentence.replace(/I\s/g, '').replace(/I'/g, '').replace(/my\s/g, '').replace(/me\s/g, ''); // Remove "I", "my", "me"
                    if (processedSentence.length > 0) {
                        summaryDelta += processedSentence + '. ';
                    }
                }

                if (summaryDelta.trim() !== '') {
                    newSummary += summaryDelta.trim() + '\n\n';
                }
            }
        }

        if (newSummary.trim() !== '') {
            fs.writeFileSync(outputFilePath, (existingSummary + '\n' + newSummary).trim() + '\n');
            console.log(`Summary updated in ${outputFilePath}`);
        } else if (existingSummary.trim() === '') {
            fs.writeFileSync(outputFilePath, "I'm thinking through how to approach this.\n");
            console.log(`Summary updated in ${outputFilePath}`);
        } else {
            console.log('No new reasoning found to update the summary.');
        }

    } catch (error) {
        console.error('An error occurred:', error);
    }
}

